"""The FrontierCS promise, enforced: a task generated by their official
Harbor adapter (see tasks/autoresearch/frontier-cs/README.md) is a valid stock Harbor
task that reef-eval can run without any reef-eval-side code."""

from pathlib import Path

import pytest

harbor = pytest.importorskip("harbor")

TASK_DIR = (
    Path(__file__).parent.parent
    / "tasks"
    / "autoresearch"
    / "frontier-cs"
    / "frontier-cs-2-0-erdos-demo"
)


def test_frontiercs_export_is_stock_harbor():
    import tomllib

    from harbor.models.task.config import TaskConfig

    cfg = TaskConfig.model_validate(tomllib.loads((TASK_DIR / "task.toml").read_text()))
    assert cfg.metadata["frontier_cs_track"] == "2.0"
    assert (TASK_DIR / "instruction.md").exists()
    assert (TASK_DIR / "environment" / "Dockerfile").exists()
    assert (TASK_DIR / "tests" / "test.sh").exists()
    assert (TASK_DIR / "solution" / "solve.sh").exists()


def test_frontiercs_iterative_submit_is_the_public_scorer_pattern():
    # Their in-task `submit.sh` is the agent's own local evaluator, which
    # reef-eval neither ingests nor trusts. The verifier decides the grade.
    env_files = {p.name for p in (TASK_DIR / "environment").iterdir()}
    assert "submit.sh" in env_files or any("submit" in p for p in env_files), (
        f"expected an agent-facing submit entry, got {sorted(env_files)}"
    )
